void sync_count_reset( Sync_Count_Obj sync  )
{
    TRACE_DEI_SYNC("\n\r[LIB.SYNC_COUNT] 0x%08X RESET \n\r", sync ); 
       
    sync->is_locked    = FALSE ;    
}

